/**
 * Day 23 — Graph. Original statements + reference solutions for the
 * in-portal Striver SDE Sheet. Expected outputs are generated by verify.
 *
 * Graph inputs: first line `n m` (nodes are 1..n), then m edges. Undirected
 * problems state so in their statement; directed problems give edges u -> v.
 * Traversals always start at node 1 and visit neighbours in ascending order.
 */

function readUndirected(lines) {
  const [n, m] = lines[0].split(/\s+/).map(Number);
  const adj = Array.from({ length: n + 1 }, () => []);
  for (let i = 1; i <= m; i++) {
    const [u, v] = lines[i].split(/\s+/).map(Number);
    adj[u].push(v);
    adj[v].push(u);
  }
  for (const list of adj) list.sort((a, b) => a - b);
  return { n, m, adj };
}

function readDirected(lines) {
  const [n, m] = lines[0].split(/\s+/).map(Number);
  const adj = Array.from({ length: n + 1 }, () => []);
  const indegree = new Array(n + 1).fill(0);
  for (let i = 1; i <= m; i++) {
    const [u, v] = lines[i].split(/\s+/).map(Number);
    adj[u].push(v);
    indegree[v]++;
  }
  for (const list of adj) list.sort((a, b) => a - b);
  return { n, m, adj, indegree };
}

